    {
      "id": 1,
      "claim": "A machine that can \"accurately tell if someone is lying\" must demonstrate high true‑positive rates and low false‑positive rates in independent, peer‑reviewed validation studies.",
      "evidence": "Standard definition of diagnostic accuracy used in psychology, medicine, and forensic science; requirement for statistical validation (e.g., sensitivity > 0.9, specificity > 0.9).",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Extensive meta‑analyses (e.g., National Research Council 2003, 2012; American Psychological Association reports) find polygraph accuracy no better than chance, with error rates ranging from 10 % to 30 % depending on conditions.",
      "evidence": "NRC reports summarizing 200+ studies; APA task force conclusions; peer‑reviewed literature showing lack of discriminative power beyond random guessing.",
      "weight": 0.45,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Because of these high error rates, polygraph results are inadmissible in the majority of U.S. federal and state courts and are excluded in many other legal systems.",
      "evidence": "Federal Rules of Evidence (Rule 702) rulings; Daubert hearings; documented court decisions (e.g., United States v. Scheffer, 1998).",
      "weight": 0.20,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "No other commercially available deception‑detection technology (e.g., functional MRI, EEG, voice‑stress analysis) has passed independent validation meeting the accuracy criteria of step 1.",
      "evidence": "Systematic reviews (e.g., Kozel et al., 2005; Lykken & Tellegen, 1996) report small sample sizes, lack of replication, and no consensus on diagnostic thresholds; no regulatory approval for forensic use.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "Since neither polygraph machines nor any other existing device satisfy the validated accuracy standards, there is currently no machine that can accurately tell if someone is lying.",
      "evidence": "Logical conjunction of steps 2‑4; absence of any technology meeting the definition in step 1.",
      "weight": 0.05,
      "depends_on": [2, 3, 4]
    }
  ],
